1 | /**
2 |  * penny-decompose.js
3 |  *
4 |  * Replays the identical simulated day (seed=42, 500 orders) and measures the
5 |  * dollars impact of each finding on every account.
6 |  *
7 |  * Sign convention: positive = account balance increases (gains money).
8 |  * The "difference" columns therefore match simulate-day.js: actual − expected.
9 |  *
10 |  * Findings measured:
11 |  *   P2  Rounding drift       – chargeTotal vs receiptTotal divergence
12 |  *   P3  Missing idempotency  – retry creates a second charge posting
13 |  *   P4  Double fees          – charge-time fee posting should not exist
14 |  *   P5  Missing cap          – settle fee not capped at $2,000
15 |  *   P6  Over refund          – refund allowed to exceed original charge
16 |  *   P1  Float noise          – residual IEEE-754 accumulation
17 |  */
18 | 
19 | import { Ledger }         from '../src/ledger.js';
20 | import { PaymentService } from '../src/payments.js';
21 | import { chargeTotal }    from '../src/invoice.js';
22 | 
23 | // ── identical PRNG / data constants from simulate-day.js ────────────────────
24 | let seed = 42;
25 | const rand = () => {
26 |   seed = (seed * 1664525 + 1013904223) % 4294967296;
27 |   return seed / 4294967296;
28 | };
29 | const pick = (arr) => arr[Math.floor(rand() * arr.length)];
30 | 
31 | const PRICES    = [150, 499.99, 1250.5, 2999.99, 7500, 18999.95, 45000, 129999.99];
32 | const CUSTOMERS = Array.from({ length: 40 }, (_, i) => `customer_${i + 1}`);
33 | const MERCHANTS = ['merchant_ada_foods', 'merchant_eko_gadgets', 'merchant_jos_textiles'];
34 | const ORDERS    = 500;
35 | const FEE_RATE  = 0.015;
36 | const FEE_CAP   = 2000; // dollars
37 | 
38 | const toCents = (dollars) => Math.round(dollars * 100);
39 | 
40 | // ── live ledger (ground truth for actual balances) ───────────────────────────
41 | const ledger = new Ledger();
42 | const svc    = new PaymentService(ledger);
43 | 
44 | // ── per-finding impact accumulators (dollars, positive = account gains) ────────
45 | const impact = {
46 |   customers:     { P2: 0, P3: 0, P4: 0, P5: 0, P6: 0 },
47 |   merchants:     { P2: 0, P3: 0, P4: 0, P5: 0, P6: 0 },
48 |   platform_fees: { P2: 0, P3: 0, P4: 0, P5: 0, P6: 0 },
49 |   clearing:      { P2: 0, P3: 0, P4: 0, P5: 0, P6: 0 },
50 | };
51 | 
52 | // ── expected accumulators (per fee schedule) ─────────────────────────────────
53 | let expCustomers = 0, expMerchants = 0, expFees = 0;
