    impact.clearing.P2       += 0;                               // nets to zero
    impact.platform_fees.P2  += drift * FEE_RATE * chargeRuns   // charge-time fee on drift
                              +  drift * FEE_RATE;               // settle-time fee on drift
    impact.merchants.P2      += drift * (1 - FEE_RATE);
