  constructor() { this.entries = []; }
  post({ ref, from, to, amount, memo = '' }) {
    this.entries.push({ ref, from, to, amount, memo });
  }
  balance(account) {
    let total = 0;
    for (const e of this.entries) {
      if (e.to   === account) total += e.amount;
      if (e.from === account) total -= e.amount;
