    const p = this.payments.get(paymentId);
    if (!p) throw new Error(`Unknown payment ${paymentId}`);

    p.refunded += amount;
    this.ledger.post({ ref: paymentId, from: p.merchant, to: p.customer, amount, memo: 'refund' });
  }
}

